1	import { useEffect, useState } from 'react';
2	import { supabase } from '../../lib/supabase';
3	import { WalletService } from '../../services/walletService';
4	import type { WalletTransaction, EscrowTransaction } from '../../services/walletService';
5	import { DollarSign, ArrowDownLeft, ArrowUpRight, History, Lock, Wallet, TrendingUp } from 'lucide-react';
6	import { useNavigate } from 'react-router-dom';
7	import DepositModal from '../../components/DepositModal';
8	
9	export default function CompanyWallet() {
10	    const navigate = useNavigate();
11	    const [loading, setLoading] = useState(true);
12	    const [balance, setBalance] = useState(0);
13	    const [transactions, setTransactions] = useState<WalletTransaction[]>([]);
14	    const [escrows, setEscrows] = useState<EscrowTransaction[]>([]);
15	    const [stats, setStats] = useState({ totalSpent: 0, inEscrow: 0 });
16	    const [isDepositModalOpen, setIsDepositModalOpen] = useState(false);
17	
18	    const fetchWalletData = async () => {
19	        const { data: { user } } = await supabase.auth.getUser();
20	        if (!user) return navigate('/login');
21	
22	        // 1. Get or create company wallet
23	        const wallet = await WalletService.getOrCreateWallet(user.id, 'company');
24	        if (wallet) {
25	            setBalance(wallet.balance);
26	        }
27	
28	        // 2. Fetch Transactions
29	        const txs = await WalletService.getTransactions(user.id);
30	        setTransactions(txs);
31	
32	        // 3. Fetch Escrows
33	        const companyEscrows = await WalletService.getCompanyEscrows(user.id);
34	        setEscrows(companyEscrows);
35	
36	        // 4. Calculate Stats
37	        const totalSpent = txs
38	            .filter(t => t.type === 'escrow_release' || (t.type === 'debit' && t.amount < 0))
39	            .reduce((acc, t) => acc + Math.abs(t.amount), 0);
40	
41	        const inEscrow = companyEscrows
42	            .filter(e => e.status === 'reserved')
43	            .reduce((acc, e) => acc + e.amount, 0);
44	
45	        setStats({ totalSpent, inEscrow });
46	
47	        setLoading(false);
48	    };
49	
50	    useEffect(() => {
51	        let isMounted = true;
52	        const init = async () => {
53	            await fetchWalletData(); // Load local data fast
54	
55	            // Background sync with Asaas silently
56	            const res = await WalletService.syncBalance();
57	            if (isMounted && res.success && res.hasUpdates) {
58	                await fetchWalletData(); // Refresh UI with new Asaas data if updates found
59	            }
60	        };
61	
62	        init();
63	        return () => { isMounted = false; };
64	    // eslint-disable-next-line react-hooks/exhaustive-deps -- init e fetchWalletData usam state setters estaveis, navigate estavel
65	    }, [navigate]);
66	
67	    const formatDate = (dateStr: string) => {
68	        return new Date(dateStr).toLocaleDateString('pt-BR', {
69	            day: '2-digit',
70	            month: 'short',
71	            year: 'numeric'
72	        });
73	    };
74	
75	    const getTransactionIcon = (type: string) => {
76	        switch (type) {
77	            case 'initial_balance': return <TrendingUp size={20} />;
78	            case 'escrow_reserve': return <Lock size={20} />;
79	            case 'escrow_release': return <ArrowUpRight size={20} />;
80	            case 'credit': return <ArrowDownLeft size={20} />;
81	            case 'platform_fee': return <DollarSign size={20} />;
82	            default: return <DollarSign size={20} />;
83	        }
84	    };
85	
86	    const getTransactionColor = (type: string, amount: number) => {
87	        if (type === 'platform_fee') {
88	            return 'text-orange-600 bg-orange-100';
89	        }
90	        if (type === 'initial_balance' || type === 'credit' || amount > 0) {
91	            return 'text-green-600 bg-green-100';
92	        }
93	        return 'text-red-600 bg-red-100';
94	    };
95	
96	    const getTransactionLabel = (t: WalletTransaction) => {
97	        if (t.type === 'credit') {
98	            return t.description || 'Deposito via PIX';
99	        }
100	        if (t.type === 'platform_fee') {
101	            return t.description || 'Taxa de servico';
102	        }
103	        return t.description || t.type;
104	    };
105	
106	    if (loading) return (
107	        <div className="flex flex-col gap-8 pb-12 max-w-4xl mx-auto animate-pulse">
108	            <div>
109	                <div className="h-10 bg-gray-200 rounded w-2/5 mb-2" />
110	                <div className="h-4 bg-gray-200 rounded w-1/2" />
111	            </div>
112	            <div className="h-36 bg-gray-200 rounded-2xl" />
113	            <div className="space-y-3">
114	                {[...Array(5)].map((_, i) => (
115	                    <div key={i} className="h-16 bg-gray-200 rounded-xl" />
116	                ))}
117	            </div>
118	        </div>
119	    );
120	
121	    return (
122	        <div className="flex flex-col gap-8 pb-12 font-sans text-accent max-w-4xl mx-auto">
123	
124	            <header>
125	                <h2 className="text-4xl font-black uppercase tracking-tighter mb-2">Carteira da Empresa</h2>
126	                <p className="text-gray-500">Gerencie seu saldo e pagamentos</p>
127	            </header>
128	
129	            {/* Main Balance Card */}
130	            <div className="bg-gradient-to-br from-blue-600 to-blue-800 text-white p-8 rounded-2xl border-2 border-black shadow-[6px_6px_0px_0px_rgba(0,0,0,1)] relative overflow-hidden">
131	                <div className="relative z-10">
132	                    <span className="text-sm font-bold uppercase text-blue-200 tracking-wider">Saldo Disponível</span>
133	                    <h2 className="text-6xl font-black tracking-tighter text-white mt-2 mb-6">R$ {balance.toFixed(2).replace('.', ',')}</h2>
134	
135	                    <div className="flex gap-4">
136	                        <button
137	                            className="flex-1 bg-white text-blue-600 py-4 rounded-xl font-black uppercase shadow-[4px_4px_0px_0px_rgba(0,0,0,0.2)] hover:shadow-none hover:translate-y-1 transition-all flex items-center justify-center gap-2"
138	                            onClick={() => navigate('/company/create')}
139	                        >
140	                            <DollarSign size={20} /> Criar Vaga
141	                        </button>
142	                        <button
143	                            className="flex-1 bg-white/10 text-white py-4 rounded-xl font-bold uppercase hover:bg-white/20 transition-colors flex items-center justify-center gap-2"
144	                            onClick={() => setIsDepositModalOpen(true)}
145	                        >
146	                            <ArrowDownLeft size={20} /> Adicionar Saldo
147	                        </button>
148	                    </div>
149	                </div>
150	                {/* Background Element */}
151	                <Wallet size={200} className="absolute -top-10 -right-10 text-white/5 rotate-12" />
152	            </div>
153	
154	            <DepositModal
155	                isOpen={isDepositModalOpen}
156	                onClose={() => setIsDepositModalOpen(false)}
157	                onSuccess={() => {
158	                    fetchWalletData();
159	                }}
160	            />
161	
162	            {/* Stats Cards */}
163	            <div className="grid grid-cols-2 gap-6">
164	                <div className="bg-white p-6 rounded-2xl border-2 border-black">
165	                    <div className="flex items-center gap-2 mb-2 text-orange-600">
166	                        <Lock size={20} /> <span className="text-xs font-black uppercase">Em Escrow</span>
167	                    </div>
168	                    <h3 className="text-2xl font-black">R$ {stats.inEscrow.toFixed(2).replace('.', ',')}</h3>
169	                    <p className="text-xs text-gray-400 mt-1">Reservado para vagas ativas</p>
170	                </div>
171	                <div className="bg-white p-6 rounded-2xl border-2 border-black">
172	                    <div className="flex items-center gap-2 mb-2 text-gray-600">
173	                        <ArrowUpRight size={20} /> <span className="text-xs font-black uppercase">Total Pago</span>
174	                    </div>
175	                    <h3 className="text-2xl font-black">R$ {stats.totalSpent.toFixed(2).replace('.', ',')}</h3>
176	                    <p className="text-xs text-gray-400 mt-1">Pagamentos a freelancers</p>
177	                </div>
178	            </div>
179	
180	            {/* Active Escrows */}
181	            {escrows.filter(e => e.status === 'reserved').length > 0 && (
182	                <section className="bg-orange-50 border-2 border-orange-200 rounded-2xl p-6">
183	                    <h3 className="text-lg font-black uppercase mb-4 flex items-center gap-2 text-orange-700">
184	                        <Lock size={20} /> Valores em Escrow
185	                    </h3>
186	                    <div className="space-y-3">
187	                        {escrows.filter(e => e.status === 'reserved').map((escrow) => (
188	                            <div key={escrow.id} className="flex justify-between items-center bg-white p-4 rounded-xl border border-orange-200">
189	                                <div>
190	                                    <h4 className="font-bold text-sm">{escrow.job?.title || 'Vaga'}</h4>
191	                                    <p className="text-xs text-gray-400">Reservado em {formatDate(escrow.created_at)}</p>
192	                                </div>
193	                                <span className="text-lg font-black text-orange-600">
194	                                    R$ {escrow.amount.toFixed(2).replace('.', ',')}
195	                                </span>
196	                            </div>
197	                        ))}
198	                    </div>
199	                </section>
200	            )}
201	
202	            {/* Transactions List */}
203	            <section className="bg-white border-2 border-black rounded-2xl p-6">
204	                <h3 className="text-lg font-black uppercase mb-6 flex items-center gap-2">
205	                    <History size={20} /> Histórico de Transações
206	                </h3>
207	
208	                <div className="space-y-4">
209	                    {transactions.length > 0 ? transactions.map((t) => (
210	                        <div key={t.id} className="flex justify-between items-center border-b border-gray-100 last:border-0 pb-4 last:pb-0">
211	                            <div className="flex items-center gap-4">
212	                                <div className={`p-3 rounded-xl ${getTransactionColor(t.type, t.amount)}`}>
213	                                    {getTransactionIcon(t.type)}
214	                                </div>
215	                                <div>
216	                                    <h4 className="font-bold text-sm">{getTransactionLabel(t)}</h4>
217	                                    <p className="text-xs text-gray-400">{formatDate(t.created_at)}</p>
218	                                </div>
219	                            </div>
220	                            <span className={`text-lg font-black ${t.type === 'platform_fee' ? 'text-orange-600' : t.amount >= 0 ? 'text-green-600' : 'text-red-600'}`}>
221	                                {t.amount >= 0 ? '+' : ''} R$ {Math.abs(t.amount).toFixed(2).replace('.', ',')}
222	                            </span>
223	                        </div>
224	                    )) : (
225	                        <div className="text-center py-8 text-gray-400">
226	                            <p className="font-bold text-sm">Nenhuma transação registrada.</p>
227	                        </div>
228	                    )}
229	                </div>
230	            </section>
231	
232	        </div>
233	    );
234	}
