1	import { useState, useEffect } from 'react';
2	import { WalletService } from '../services/walletService';
3	import { Loader2, X, ExternalLink, CreditCard, Landmark, Smartphone, Wallet } from 'lucide-react';
4	import { useToast } from '../contexts/ToastContext';
5	import { useFocusTrap } from '../hooks/useFocusTrap';
6	import { supabase } from '../lib/supabase';
7	
8	interface DepositModalProps {
9	    isOpen: boolean;
10	    onClose: () => void;
11	    onSuccess: () => void;
12	}
13	
14	const PAYMENT_METHODS = [
15	    { value: 'PIX', label: 'PIX', icon: Smartphone, tag: 'Instantaneo' },
16	    { value: 'CREDIT_CARD', label: 'Cartao de Credito', icon: CreditCard, tag: 'Imediato' },
17	    { value: 'BOLETO', label: 'Boleto Bancario', icon: Landmark, tag: '1-3 dias' },
18	    { value: 'UNDEFINED', label: 'Escolher depois', icon: Wallet, tag: 'Na fatura' },
19	];
20	
21	const SERVICE_FEE_PCT = 0.08;
22	const PROCESSING_FEE = 4.00;
23	const MIN_DEPOSIT = 50;
24	
25	export default function DepositModal({ isOpen, onClose, onSuccess }: DepositModalProps) {
26	    const { addToast } = useToast();
27	    const [amount, setAmount] = useState<string>('');
28	    const [billingType, setBillingType] = useState<string>('PIX');
29	    const [invoiceUrl, setInvoiceUrl] = useState<string | null>(null);
30	    const [loading, setLoading] = useState(false);
31	    const [userDoc, setUserDoc] = useState<{ name: string; cpfCnpj: string } | null>(null);
32	    const trapRef = useFocusTrap(isOpen);
33	
34	    useEffect(() => {
35	        if (isOpen) {
36	            setAmount('');
37	            setBillingType('PIX');
38	            setInvoiceUrl(null);
39	
40	            (async () => {
41	                const { data: { user } } = await supabase.auth.getUser();
42	                if (!user) return;
43	                const userType = user.user_metadata?.user_type;
44	                if (userType === 'hire') {
45	                    let { data } = await supabase.from('companies').select('name, cnpj').eq('owner_id', user.id).single();
46	                    if (!data) {
47	                        ({ data } = await supabase.from('companies').select('name, cnpj').eq('id', user.id).single());
48	                    }
49	                    if (data) setUserDoc({ name: data.name || '', cpfCnpj: data.cnpj || '' });
50	                } else {
51	                    const { data } = await supabase.from('workers').select('full_name, cpf').eq('id', user.id).single();
52	                    if (data) setUserDoc({ name: data.full_name || '', cpfCnpj: data.cpf || '' });
53	                }
54	            })();
55	        }
56	    }, [isOpen, trapRef]);
57	
58	    if (!isOpen) return null;
59	
60	    const depositVal = parseFloat(amount.replace(',', '.')) || 0;
61	    const serviceFee = parseFloat((depositVal * SERVICE_FEE_PCT).toFixed(2));
62	    const creditAmount = depositVal > 0 ? Math.max(0, parseFloat((depositVal - serviceFee - PROCESSING_FEE).toFixed(2))) : 0;
63	    const isValid = depositVal >= MIN_DEPOSIT && depositVal <= 50000;
64	
65	    const handleInitiate = async () => {
66	        if (!isValid) {
67	            addToast(`Valor minimo: R$ ${MIN_DEPOSIT},00`, 'error');
68	            return;
69	        }
70	        if (!userDoc?.cpfCnpj) {
71	            addToast('CPF ou CNPJ nao encontrado. Atualize seu perfil.', 'error');
72	            return;
73	        }
74	
75	        setLoading(true);
76	        const result = await WalletService.createDeposit({
77	            amount: depositVal,
78	            name: userDoc.name,
79	            cpfCnpj: userDoc.cpfCnpj,
80	            billingType,
81	        });
82	        setLoading(false);
83	
84	        if (result.invoiceUrl || result.pixQrCodeUrl) {
85	            setInvoiceUrl(result.invoiceUrl || result.pixQrCodeUrl || null);
86	        } else {
87	            addToast(result.error || 'Erro ao gerar fatura', 'error');
88	        }
89	    };
90	
91	    const handleClose = () => {
92	        if (invoiceUrl) onSuccess();
93	        onClose();
94	    };
95	
96	    return (
97	        <div
98	            className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm"
99	            onClick={(e) => { if (e.target === e.currentTarget) handleClose(); }}
100	            onKeyDown={(e) => { if (e.key === 'Escape') handleClose(); }}
101	        >
102	            <div
103	                ref={trapRef}
104	                role="dialog"
105	                aria-modal="true"
106	                aria-labelledby="deposit-title"
107	                className="bg-white rounded-2xl w-full max-w-[440px] relative animate-in fade-in zoom-in-95 duration-200 shadow-2xl overflow-hidden"
108	            >
109	                {/* Header — compact, Stripe-like */}
110	                <div className="bg-gray-50 border-b border-gray-200 px-6 py-4 flex items-center justify-between">
111	                    <h3 id="deposit-title" className="text-lg font-bold text-gray-900">Adicionar creditos</h3>
112	                    <button
113	                        onClick={handleClose}
114	                        aria-label="Fechar"
115	                        className="text-gray-400 hover:text-gray-900 transition-colors w-8 h-8 rounded-lg flex items-center justify-center hover:bg-gray-200"
116	                    >
117	                        <X size={18} />
118	                    </button>
119	                </div>
120	
121	                {!invoiceUrl ? (
122	                    <div className="p-6 space-y-5">
123	
124	                        {/* Amount input */}
125	                        <div>
126	                            <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1.5">Valor</label>
127	                            <div className="relative">
128	                                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 font-semibold text-lg">R$</span>
129	                                <input
130	                                    type="number"
131	                                    aria-label="Valor do deposito"
132	                                    value={amount}
133	                                    onChange={(e) => setAmount(e.target.value)}
134	                                    min={MIN_DEPOSIT}
135	                                    className="w-full border border-gray-300 rounded-lg pl-12 pr-4 py-3 focus:border-black focus:ring-1 focus:ring-black outline-none font-bold text-xl text-gray-900 transition-all placeholder:text-gray-300 placeholder:font-normal"
136	                                    placeholder={`${MIN_DEPOSIT},00`}
137	                                    autoFocus
138	                                />
139	                            </div>
140	                            {depositVal > 0 && depositVal < MIN_DEPOSIT && (
141	                                <p className="text-xs text-red-500 mt-1 font-medium">Minimo R$ {MIN_DEPOSIT},00</p>
142	                            )}
143	                        </div>
144	
145	                        {/* Payment method tabs — Stripe style */}
146	                        <div>
147	                            <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1.5">Forma de pagamento</label>
148	                            <div className="flex gap-1 bg-gray-100 p-1 rounded-lg">
149	                                {PAYMENT_METHODS.map(method => {
150	                                    const Icon = method.icon;
151	                                    const selected = billingType === method.value;
152	                                    return (
153	                                        <button
154	                                            key={method.value}
155	                                            type="button"
156	                                            onClick={() => setBillingType(method.value)}
157	                                            className={`flex-1 py-2 px-1 rounded-md text-center transition-all ${
158	                                                selected
159	                                                    ? 'bg-white shadow-sm text-gray-900 font-bold'
160	                                                    : 'text-gray-500 hover:text-gray-700'
161	                                            }`}
162	                                        >
163	                                            <Icon size={18} className="mx-auto mb-0.5" />
164	                                            <span className="text-[10px] block leading-tight">{method.label}</span>
165	                                        </button>
166	                                    );
167	                                })}
168	                            </div>
169	                            <p className="text-[11px] text-gray-400 mt-1.5 text-center">
170	                                {PAYMENT_METHODS.find(m => m.value === billingType)?.tag}
171	                            </p>
172	                        </div>
173	
174	                        {/* Fee breakdown — only shows when amount is valid */}
175	                        {isValid && (
176	                            <div className="border border-gray-200 rounded-lg overflow-hidden">
177	                                <div className="divide-y divide-gray-100">
178	                                    <div className="flex justify-between px-4 py-2.5 text-sm">
179	                                        <span className="text-gray-500">Deposito</span>
180	                                        <span className="font-semibold text-gray-900">R$ {depositVal.toFixed(2).replace('.', ',')}</span>
181	                                    </div>
182	                                    <div className="flex justify-between px-4 py-2.5 text-sm">
183	                                        <span className="text-gray-500">Taxa Worki (8%)</span>
184	                                        <span className="font-semibold text-gray-500">- R$ {serviceFee.toFixed(2).replace('.', ',')}</span>
185	                                    </div>
186	                                    <div className="flex justify-between px-4 py-2.5 text-sm">
187	                                        <span className="text-gray-500">Operador financeiro</span>
188	                                        <span className="font-semibold text-gray-500">- R$ {PROCESSING_FEE.toFixed(2).replace('.', ',')}</span>
189	                                    </div>
190	                                </div>
191	                                <div className="flex justify-between px-4 py-3 bg-gray-50 border-t border-gray-200">
192	                                    <span className="font-bold text-gray-900">Credito no saldo</span>
193	                                    <span className="font-bold text-lg text-green-600">R$ {creditAmount.toFixed(2).replace('.', ',')}</span>
194	                                </div>
195	                            </div>
196	                        )}
197	
198	                        {/* Info text */}
199	                        <p className="text-[11px] text-gray-400 text-center leading-relaxed">
200	                            Ao contratar, o valor debitado e exatamente o orcamento do job. Sem custos extras.
201	                        </p>
202	
203	                        {/* Submit button */}
204	                        <button
205	                            onClick={handleInitiate}
206	                            disabled={loading || !isValid}
207	                            className="w-full bg-black text-white py-3.5 rounded-lg font-bold text-sm hover:bg-gray-800 transition-all flex justify-center items-center gap-2 disabled:opacity-40 disabled:cursor-not-allowed"
208	                        >
209	                            {loading ? (
210	                                <Loader2 className="animate-spin" size={18} />
211	                            ) : (
212	                                <>Pagar R$ {depositVal > 0 ? depositVal.toFixed(2).replace('.', ',') : '0,00'}</>
213	                            )}
214	                        </button>
215	
216	                        <p className="text-[10px] text-gray-300 text-center">
217	                            Pagamento processado com seguranca pelo Asaas
218	                        </p>
219	                    </div>
220	                ) : (
221	                    /* Success state */
222	                    <div className="p-6 space-y-5">
223	                        <div className="text-center py-2">
224	                            <div className="w-14 h-14 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-3">
225	                                <svg className="w-7 h-7 text-green-600" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
226	                                    <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
227	                                </svg>
228	                            </div>
229	                            <h4 className="text-lg font-bold text-gray-900">Fatura gerada</h4>
230	                            <p className="text-sm text-gray-500 mt-1">
231	                                Clique abaixo para abrir e pagar. O credito sera adicionado automaticamente apos a confirmacao.
232	                            </p>
233	                        </div>
234	
235	                        <a
236	                            href={invoiceUrl}
237	                            target="_blank"
238	                            rel="noopener noreferrer"
239	                            className="w-full bg-black text-white py-3.5 rounded-lg font-bold text-sm hover:bg-gray-800 transition-all flex justify-center items-center gap-2"
240	                        >
241	                            <ExternalLink size={16} />
242	                            Abrir fatura de pagamento
243	                        </a>
244	
245	                        <button
246	                            onClick={handleClose}
247	                            className="w-full py-2.5 text-sm font-semibold text-gray-500 hover:text-gray-900 transition-colors"
248	                        >
249	                            Ja paguei / Fechar
250	                        </button>
251	                    </div>
252	                )}
253	            </div>
254	        </div>
255	    );
256	}
