70	export const PaymentMethodService = {
71	  /**
72	   * Tokeniza e salva um cartão de crédito da empresa.
73	   *
74	   * Invoca a Edge Function `asaas-tokenize-card` (Article 10: PAN não passa pelo DB).
75	   * Idempotente: re-tokenizar o mesmo cartão não cria linha duplicada (UNIQUE company+token).
76	   *
77	   * @param input Dados do cartão (PAN + holderInfo).
78	   * @returns { success, paymentMethodId, brand, last4 } ou { success: false, error }.
79	   */
80	  async savePaymentMethod(input: SaveCardInput): Promise<SaveCardResult> {
81	    try {
82	      const result = await invokeFunction<{
83	        success: boolean;
84	        paymentMethodId?: string;
85	        brand?: string | null;
86	        last4?: string | null;
87	        error?: string;
88	      }>('asaas-tokenize-card', input as unknown as Record<string, unknown>);
89	
90	      if (!result.success) {
91	        return { success: false, error: result.error || 'Erro ao salvar cartão.' };
92	      }
93	
94	      return {
95	        success: true,
96	        paymentMethodId: result.paymentMethodId,
97	        brand: result.brand,
98	        last4: result.last4,
99	      };
100	    } catch (error: unknown) {
101	      logError('paymentMethodService.savePaymentMethod', error);
102	      return {
103	        success: false,
104	        error: error instanceof Error ? error.message : 'Erro ao salvar cartão.',
105	      };
106	    }
107	  },
108	
109	  /**
110	   * Lista os métodos de pagamento cadastrados pela empresa autenticada.
111	   * Leitura direta via supabase (RLS garante isolamento por dono).
112	   */
113	  async listPaymentMethods(): Promise<PaymentMethod[]> {
114	    try {
115	      const { data: { user } } = await supabase.auth.getUser();
116	      if (!user) return [];
117	
118	      // Resolver company_id a partir do owner_id
119	      const { data: company, error: companyErr } = await supabase
120	        .from('companies')
121	        .select('id')
122	        .eq('owner_id', user.id)
123	        .maybeSingle();
124	
125	      if (companyErr || !company) return [];
126	
127	      const { data, error } = await supabase
128	        .from('payment_methods')
129	        .select('id, company_id, brand, last4, holder_name, is_default, created_at, updated_at')
130	        .eq('company_id', company.id)
131	        .order('is_default', { ascending: false })
132	        .order('created_at', { ascending: false });
133	
134	      if (error) {
135	        logError('paymentMethodService.listPaymentMethods', error);
136	        return [];
137	      }
138	
139	      // Não expor asaas_credit_card_token na listagem (PCI — token opaco, mas desnecessário na UI)
140	      return (data ?? []) as PaymentMethod[];
141	    } catch (error: unknown) {
142	      logError('paymentMethodService.listPaymentMethods', error);
143	      return [];
144	    }
145	  },
146	
147	  /**
148	   * Retorna o método de pagamento default da empresa autenticada, ou null.
149	   */
150	  async getDefaultPaymentMethod(): Promise<PaymentMethod | null> {
151	    try {
152	      const { data: { user } } = await supabase.auth.getUser();
153	      if (!user) return null;
154	
155	      const { data: company } = await supabase
156	        .from('companies')
157	        .select('id')
158	        .eq('owner_id', user.id)
159	        .maybeSingle();
160	
161	      if (!company) return null;
162	
163	      const { data } = await supabase
164	        .from('payment_methods')
165	        .select('id, company_id, brand, last4, holder_name, is_default, created_at, updated_at')
166	        .eq('company_id', company.id)
167	        .eq('is_default', true)
168	        .maybeSingle();
169	
170	      return (data as PaymentMethod | null);
171	    } catch (error: unknown) {
172	      logError('paymentMethodService.getDefaultPaymentMethod', error);
173	      return null;
174	    }
175	  },
176	
177	  /**
178	   * Captura o pagamento postpago de um turno concluído.
179	   *
180	   * Para turnos kind='postpaid': invoca asaas-capture-payment (captura o hold ou charge_on_demand).
181	   * NÃO deve ser chamado para turnos prepago (esses usam WalletService.releaseEscrow).
182	   *
183	   * Idempotente: recapturar não duplica crédito.
184	   */
185	  async capturePayment(jobId: string, workerId: string): Promise<CapturePaymentResult> {
186	    try {
187	      const result = await invokeFunction<{ success: boolean; chargeOnDemand?: boolean; error?: string }>(
188	        'asaas-capture-payment',
189	        { jobId, workerId }
190	      );
191	
192	      return {
193	        success: result.success,
194	        chargeOnDemand: result.chargeOnDemand,
195	      };
196	    } catch (error: unknown) {
197	      logError('paymentMethodService.capturePayment', error);
198	      return {
199	        success: false,
200	        error: error instanceof Error ? error.message : 'Erro ao capturar pagamento.',
201	      };
202	    }
203	  },
204	
205	  /**
206	   * Libera o hold postpago (cancelamento / no-show antes da captura).
207	   * Invoca asaas-release-hold (RPC release_hold_postpago + DELETE no Asaas).
208	   * Idempotente: escrow já refunded → success silencioso.
